-- Guarded cleanup of inert legacy resource child pools, batch 06.
-- Physical gameobject rows are untouched.
START TRANSACTION;
DELETE pp FROM pool_pool pp LEFT JOIN pool_creature pc ON pc.pool_entry=pp.pool_id LEFT JOIN pool_gameobject pg ON pg.pool_entry=pp.pool_id LEFT JOIN pool_quest pq ON pq.pool_entry=pp.pool_id LEFT JOIN game_event_pool gep ON gep.pool_entry=pp.pool_id LEFT JOIN pool_pool child ON child.mother_pool=pp.pool_id WHERE pp.pool_id IN (2055,2060,2072,2075,2076,2077,2078,2079,2081,2083,2085,2086,2088,2089,2090,2092,2093,2101,2106,2107,2109,2111,2113,2114,2121,2124,2125,2127,2134,2138,2139,2140,2146,2147,2149,2150,2153,2154,2161,2167,2171,2172,2173,2177,2178,2181,2185,2187,2190,2193) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND child.pool_id IS NULL;
DELETE pt FROM pool_template pt LEFT JOIN pool_creature pc ON pc.pool_entry=pt.entry LEFT JOIN pool_gameobject pg ON pg.pool_entry=pt.entry LEFT JOIN pool_quest pq ON pq.pool_entry=pt.entry LEFT JOIN game_event_pool gep ON gep.pool_entry=pt.entry LEFT JOIN pool_pool pp_child ON pp_child.pool_id=pt.entry LEFT JOIN pool_pool pp_mother ON pp_mother.mother_pool=pt.entry WHERE pt.entry IN (2055,2060,2072,2075,2076,2077,2078,2079,2081,2083,2085,2086,2088,2089,2090,2092,2093,2101,2106,2107,2109,2111,2113,2114,2121,2124,2125,2127,2134,2138,2139,2140,2146,2147,2149,2150,2153,2154,2161,2167,2171,2172,2173,2177,2178,2181,2185,2187,2190,2193) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND pp_child.pool_id IS NULL AND pp_mother.pool_id IS NULL;
COMMIT;

